import{z as i,x as p,o as B,c as A,q as o,j as s,D as r,d as t,s as E,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"分块","description":"","frontmatter":{"title":"分块","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sqrt-decomposition.md","filePath":"cs/sqrt-decomposition.md","lastUpdated":1791413859000}'),d={name:"cs/sqrt-decomposition.md"};function c(m,a,D,h,f,C){const n=p("Mermaid");return B(),A("div",null,[a[2]||(a[2]=o('<h1 id="分块" tabindex="-1">分块 <a class="header-anchor" href="#分块" aria-label="Permalink to &quot;分块&quot;">​</a></h1><div class="epigraph"><p>把序列切成约 $\\sqrt{n}$ 长的段，整块用摘要、零头用扫；查询更新都落在「几个整块加两小段」上。</p><footer>—— 据 Sedgewick and Wayne；Knuth, TAOCP；Bentley, Programming Pearls 对分治与块状布局的整理</footer></div><p><a href="/cs/monotonic-stack-queue">上一课</a>吃掉了扫描型近邻。查询若是任意 \\([l,r]\\)、操作又不止最值或加法，线段树要为每种 \\(\\mathrm{op}\\) 设计节点。有时实现一块整段摘要更快。<a href="/cs/array-random-access">数组</a>本来就连续。本课不重写单调队列。缺口是分块（sqrt decomposition）：块长 \\(B\\approx\\sqrt{n}\\)，用时间在 \\(O(B)\\) 与 \\(O(n/B)\\) 之间折中。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个元素，\\(m\\) 次操作。若每次扫全表 \\(\\Theta(n)\\) 太慢；若写完整线段树，标记与合并可能比问题本身重。分块：下标 \\([1,B],[B+1,2B],\\ldots\\)。每块存一个摘要（和、懒加、排序副本、众数候选……视问题而定）。查询跨块：左零头、右零头暴力，中间整块用摘要。缺口是<strong>把区间切成 \\(O(n/B)\\) 整块加 \\(O(B)\\) 零头</strong>，令 \\(B=\\sqrt{n}\\) 时两边都是 \\(O(\\sqrt{n})\\)。</p><p><span class="marginnote">块长不必精确 \\(\\sqrt{n}\\)；常数随摘要成本和 cache 行调整。思想是平衡「扫零头」与「点多少块」。</span></p><p><span class="marginnote">直觉类比：图书馆不把 10 万本书排成一长排（找一本要走 10 万步），也不每本书一个柜子（柜子要翻 10 万个），而是每架约 316 本——先按架号定位再架内翻，两段都不超过几百步，这正是 \\(\\sqrt{100000}\\approx316\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建块 \\(\\Theta(n)\\)。点修：改 \\(A[i]\\) 并重算该块摘要，常 \\(O(B)\\)（若摘要是和则 \\(O(1)\\)）。区间操：零头暴力，整块打块级懒标记或改摘要。查询对称。</p>',9)),(B(),s(l,null,{default:r(()=>[E(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E4%B8%8B%E6%A0%87%201..n%22%5D%20--%3E%20BLK%5B%22%E5%9D%97%E9%95%BF%20B%22%5D%0A%20%20Q%5B%22%5Bl%2C%20r%5D%5D%20--%3E%20TAIL%5B%E5%B7%A6%E5%8F%B3%E9%9B%B6%E5%A4%B4%20O(B)%22%5D%0A%20%20Q%20--%3E%20MID%5B%22%E4%B8%AD%E9%97%B4%E6%95%B4%E5%9D%97%20O(n%2FB)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与线段树：分块代码短、局部性好、改需求时摘要好换；渐近常多一个 \\(\\sqrt{n}\\)。与稀疏表：分块易加更新。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"总时间 \\(O((n+m)\\sqrt{n})\\) 是常见合同，不是唯一。块内排序后的二次块（再按值分）可做区间第 \\(k\\) 类问题，本课只点名：仍是「块摘要 + 零头」。下标换算：\\(i\\) 所在块 \\(\\lfloor(i-1)/B\\rfloor\\)，不要每次除法写错边界。",-1)),(B(),s(l,null,{default:r(()=>[E(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%8D%95%E6%AC%A1%E5%8C%BA%E9%97%B4%E6%93%8D%E4%BD%9C%E4%BB%A3%E4%BB%B7%20%3D%20%E9%9B%B6%E5%A4%B4%20%2B%20%E6%95%B4%E5%9D%97%3Cbr%2F%3E%E7%BA%A6%20B%20%2B%20n%2FB%22%5D%20--%3E%20B1%5B%22B%20%E8%BF%87%E5%B0%8F%2C%20%E5%A6%82%20B%3D10%22%5D%0A%20%20T%20--%3E%20B2%5B%22B%20%E7%BA%A6%20sqrt%20n%2C%20%E4%B8%A4%E4%BE%A7%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20T%20--%3E%20B3%5B%22B%20%E8%BF%87%E5%A4%A7%2C%20%E5%A6%82%20B%3Dn%22%5D%0A%20%20B1%20--%3E%20C1%5B%22%E9%9B%B6%E5%A4%B4%E4%BE%BF%E5%AE%9C%2C%20%E4%BD%86%E6%95%B4%E5%9D%97%E5%A4%9A%E8%BE%BE%20n%2FB%3Cbr%2F%3En%3D10000%20%E6%97%B6%201000%20%E5%9D%97%22%5D%0A%20%20B2%20--%3E%20C2%5B%22B%3D100%2C%20%E9%9B%B6%E5%A4%B4%E8%87%B3%E5%A4%9A%E7%BA%A6%20200%2C%20%E6%95%B4%E5%9D%97%20100%3Cbr%2F%3E%E5%90%88%E8%AE%A1%E7%BA%A6%20300%22%5D%0A%20%20B3%20--%3E%20C3%5B%22%E5%9D%97%E5%B0%91%2C%20%E4%BD%86%E9%9B%B6%E5%A4%B4%E9%80%80%E5%8C%96%E6%88%90%E6%89%AB%E5%85%A8%E8%A1%A8%20n%22%5D%0A%20%20C2%20--%3E%20OPT%5B%22B%20%2B%20n%2FB%20%E5%9C%A8%20B%3Dsqrt%20n%20%E5%8F%96%E6%9C%80%E5%B0%8F%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><a href="/cs/locality-principle">局部性</a>：整块顺序扫对 cache 友好，这是分块相对指针树的实际优势。</p><p><span class="marginnote">数字实例：\\(n=10000\\) 时取 \\(B=100\\)——一次区间查询左零头至多 99 个元素、右零头至多 99 个、中间至多 100 个整块，合计约 300 次访问，比扫全表的 10000 次快约 33 倍；块内存和时点修只重算 1 个块的 100 个元素。</span></p><p><span class="marginnote">常见误区：下标换算忘减一。0 起点时块号是 \\(\\lfloor i/B\\rfloor\\)，1 起点是 \\(\\lfloor(i-1)/B\\rfloor\\)——混用后最后一个元素的块号越界，典型症状是建块数组少一格、区间查询漏掉末尾整块。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把莫队的块序排序写进来——那是下一课把<strong>离线询问</strong>按块重排。也不把二维分块、树分块写完。实时最坏若必须 \\(O(\\log n)\\)，仍用树。</p><p>后课默认：在线、摘要好写时分块够用。一堆静态询问要来回扩缩区间，用莫队。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分块：\\(B\\approx\\sqrt{n}\\)，零头加整块摘要。</li><li>实现短、易改；渐近常逊于线段树。</li><li>离线询问的块序是莫队。</li><li>出处：Sedgewick and Wayne；Knuth；Bentley。</li></ul>',8))])}const T=i(d,[["render",c]]);export{u as __pageData,T as default};
